"""Variants of a product phase generated by an orientation relationship (OR)."""
import numpy as np

from .orient import point_group, rot


def _frame(n, d):
    n = n / np.linalg.norm(n)
    d = d - (d @ n) * n                      # orthogonalise (pseudo-symmetric metrics)
    d = d / np.linalg.norm(d)
    return np.stack([n, d, np.cross(n, d)], 1)


def or_rotation(LP, LH, plane_P, plane_H, dir_P, dir_H):
    """Rotation R taking product-crystal Cartesian vectors to parent-crystal ones,
    for the OR (plane_P) || (plane_H), [dir_P] || [dir_H]."""
    FP = _frame(LP.plane_normal(plane_P), LP.direction(dir_P))
    FH = _frame(LH.plane_normal(plane_H), LH.direction(dir_H))
    return FP @ FH.T


def variant_rotations(R, group_P, group_H):
    """Distinct variants R_k = S_P R (S_P in parent group) modulo product symmetry."""
    GP, GH = point_group(group_P), point_group(group_H)
    out = []
    for S in GP:
        Rk = S @ R
        if not any(np.allclose(np.linalg.inv(o) @ Rk, h, atol=1e-6) for o in out for h in GH):
            out.append(Rk)
    return np.array(out)


def distinct_axes(vectors, tol=1e-6):
    """Distinct axial directions (v ~ -v) in a list of unit vectors."""
    out = []
    for v in vectors:
        if not any(abs(abs(v @ o) - 1) < tol for o in out):
            out.append(v)
    return np.array(out)


def twin_rotation(LH, axis_hkl, angle_deg, axis_is_plane_normal=True):
    """Twin operation (product-crystal frame): rotation by angle about a plane normal
    or a direction of the product lattice."""
    ax = LH.plane_normal(axis_hkl) if axis_is_plane_normal else LH.direction(axis_hkl)
    return rot(ax, angle_deg)


def axis_angle_deg(u, v):
    c = abs(np.dot(u, v)) / (np.linalg.norm(u) * np.linalg.norm(v))
    return float(np.degrees(np.arccos(np.clip(c, -1, 1))))
